const V='2.3.1';
// Typhoon simulation model (gameplay approximations based on public performance data).
// Internal game units: fuel is % of a 7,600 kg full-fuel load.
// External tanks/AAR are represented separately. Burn varies with speed and manoeuvre.
const TYPHOON = {
  internalFuelKg: 7600,
  maxSpeedKt: 1300,
  maxAltitudeFt: 55000,
  climbRateFtMin: 3200,
  descentRateFtMin: 5000
};
const fuelRateKgH=f=>{
 const altitude=(f.alt||0)*100;
 const level=altitude>=36000?'high':altitude>=20000?'medium':'sea';
 if(f.reheat)return {sea:30000,medium:22000,high:15500}[level];
 if((f.s||0)>=850)return {sea:30000,medium:8200,high:5500}[level];
 return {sea:4500,medium:3100,high:2200}[level];
};
const fuelBurnPercentPerMinute=f=>fuelRateKgH(f)/60/TYPHOON.internalFuelKg*100;
const fuelEnduranceMinutes=f=>Math.max(0,Math.floor((f.fuel||0)/fuelBurnPercentPerMinute(f)));
const climbMinutes = (fromFt,toFt) => {
  const delta=Math.max(0,toFt-fromFt);
  return delta/TYPHOON.climbRateFtMin;
};
const scrambleDelayMinutes = () => {
  // Triangular distribution: 2–6 minutes, weighted toward a four-minute response.
  const a=2,b=6,m=4;
  const u=Math.random();
  return u < (m-a)/(b-a)
    ? a+Math.sqrt(u*(b-a)*(m-a))
    : b-Math.sqrt((1-u)*(b-a)*(b-m));
};

const normaliseTargetAltitude=(t)=>{
  if(t.friendly) return t;
  // Most game targets operate in plausible high-level controlled airspace.
  const floors=[18000,22000,26000,28000,32000,36000];
  return {...t,altitude:t.altitude && t.altitude>=18000 ? t.altitude : floors[Math.floor(Math.random()*floors.length)]};
};

const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const norm=a=>(a%360+360)%360;
const MAP={minLon:-12,maxLon:18,minLat:48,maxLat:66};
const RADAR_VERTICAL_SCALE=1.25;
const geoPoint=point=>{const lat=Number(point?.lat),lon=Number(point?.lon);if(Number.isFinite(lat)&&Number.isFinite(lon))return {lat,lon};const x=Number(point?.x)||0,y=Number(point?.y)||0;return {lon:MAP.minLon+x/100*(MAP.maxLon-MAP.minLon),lat:MAP.maxLat-((y+12.5)/RADAR_VERTICAL_SCALE)/100*(MAP.maxLat-MAP.minLat)}};
const latLonToMap=({lat,lon})=>({x:((lon-MAP.minLon)/(MAP.maxLon-MAP.minLon))*100,y:-12.5+((MAP.maxLat-lat)/(MAP.maxLat-MAP.minLat))*100*RADAR_VERTICAL_SCALE});
const mapPosition=point=>latLonToMap(geoPoint(point));
const withPosition=point=>({...point,...geoPoint(point),...latLonToMap(geoPoint(point))});
const formatLatitude=point=>{const {lat}=geoPoint(point);return `${Math.abs(lat).toFixed(3)}°${lat>=0?'N':'S'}`};
const formatLongitude=point=>{const {lon}=geoPoint(point);return `${Math.abs(lon).toFixed(3)}°${lon>=0?'E':'W'}`};
const bearing=(a,b)=>{const from=geoPoint(a),to=geoPoint(b),r=Math.PI/180,delta=(to.lon-from.lon)*r,y=Math.sin(delta)*Math.cos(to.lat*r),x=Math.cos(from.lat*r)*Math.sin(to.lat*r)-Math.sin(from.lat*r)*Math.cos(to.lat*r)*Math.cos(delta);return Math.round(norm(Math.atan2(y,x)/r));};
const distance=(a,b)=>{const from=geoPoint(a),to=geoPoint(b),r=Math.PI/180,dLat=(to.lat-from.lat)*r,dLon=(to.lon-from.lon)*r,h=Math.sin(dLat/2)**2+Math.cos(from.lat*r)*Math.cos(to.lat*r)*Math.sin(dLon/2)**2;return 3440.065*Math.atan2(Math.sqrt(h),Math.sqrt(1-h));};
const moveAlongTrack=(point,heading,distanceNm)=>{const from=geoPoint(point),r=Math.PI/180,d=distanceNm/3440.065,brg=heading*r,lat1=from.lat*r,lon1=from.lon*r,lat2=Math.asin(Math.sin(lat1)*Math.cos(d)+Math.cos(lat1)*Math.sin(d)*Math.cos(brg)),lon2=lon1+Math.atan2(Math.sin(brg)*Math.sin(d)*Math.cos(lat1),Math.cos(d)-Math.sin(lat1)*Math.sin(lat2));return withPosition({...point,lat:lat2/r,lon:norm(lon2/r+180)-180});};
const turnTowards=(current,target,maxDegrees)=>{if(target==null)return norm(current);const delta=((target-current+540)%360)-180;return Math.abs(delta)<=maxDegrees?norm(target):norm(current+Math.sign(delta)*maxDegrees)};
const PILOT_RADAR_CONTACT_NM=45;
const PILOT_VISUAL_CONTACT_NM=2;
const OWN_RADAR_INTERCEPT_NM=20;
// Standard-rate turns are approximately 3° per second: 30° between 10-second radar sweeps.
const HOSTILE_TURN_DEGREES_PER_SWEEP=30;
