 withPosition({id:'RI21',name:'RIGID 21',squawk:'4203',lat:53.093,lon:-0.167,h:20,s:0,alt:0,fuel:100,airborne:false,base:'CON',pair:2,status:'STANDBY'}),
 withPosition({id:'RI22',name:'RIGID 22',squawk:'4204',lat:53.093,lon:-0.167,h:20,s:0,alt:0,fuel:100,airborne:false,base:'CON',pair:2,status:'STANDBY',followLeaderId:'RI21'})
