 const scramble=()=>{if(!canLaunch(f))return;const delay=+scrambleDelayMinutes().toFixed(1);update(s=>{const launchIds=s.fighters.filter(x=>x.base===f.base&&x.pair===f.pair&&canLaunch(x)).map(x=>x.id),launching=s.fighters.filter(x=>launchIds.includes(x.id));const first=s.mission.firstScramble[f.base],names=launching.map(x=>x.name).join(' / ');return {...s,mission:{...s.mission,firstScramble:{...s.mission.firstScramble,[f.base]:first??s.elapsed}},fighters:s.fighters.map(x=>{if(!launchIds.includes(x.id))return x;const departure=bases.find(b=>b.id===x.base),failure=Math.random()<.05;return {...x,lat:departure.lat,lon:departure.lon,x:departure.x,y:departure.y,airborne:false,status:`SCRAMBLING · ${delay} MIN`,scrambleAt:s.elapsed,scrambleDelay:delay,failureAt:failure?s.elapsed+delay+5+Math.floor(Math.random()*12):null,fuel:100};}),radio:[`${clock}  QRA OPS: SCRAMBLE ${names} — PAIRED LAUNCH — PILOT REPORT ETA ${delay} MIN`,...s.radio].slice(0,10)}});speak(`Scramble. Scramble. Scramble. ${f.name} and paired aircraft. Immediate launch.`)};
